package net.civeira.phylax.feature.observe.observabilityconfig.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observabilityconfig.domain.ObservabilityConfig;
import net.civeira.phylax.feature.observe.observabilityconfig.domain.valueobject.RetentionHoursDebugVO;

class RetentionHoursDebugValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of retention hours debug of observability config")
  void test_retention_hours_debug_value_holder_assign_plain_value() {
    Object holder = new Object();
    RetentionHoursDebugValueHolder<Object> value = new RetentionHoursDebugValueHolder<>(holder);
    Assertions.assertSame(holder, value.retentionHoursDebug(1), "Setters must return the holder");
    Assertions.assertTrue(value.getRetentionHoursDebugValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals(1, value.getRetentionHoursDebug().orElse(null),
        "The plain value must be recovered");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of retention hours debug of observability config")
  void test_retention_hours_debug_value_holder_assign_value_object() {
    Object holder = new Object();
    RetentionHoursDebugValueHolder<Object> value = new RetentionHoursDebugValueHolder<>(holder);
    RetentionHoursDebugVO vo = RetentionHoursDebugVO.from(1);
    Assertions.assertFalse(value.getRetentionHoursDebugValue().isPresent(),
        "A new holder must be empty");
    Assertions.assertSame(holder, value.retentionHoursDebug(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getRetentionHoursDebugValue().orElseThrow());
    Assertions.assertSame(holder, value.retentionHoursDebug(Optional.empty()));
    Assertions.assertFalse(value.getRetentionHoursDebugValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.retentionHoursDebug(Optional.of(vo)));
    Assertions.assertSame(vo, value.getRetentionHoursDebugValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of retention hours debug of observability config against the original")
  void test_retention_hours_debug_value_holder_read() {
    Object holder = new Object();
    RetentionHoursDebugValueHolder<Object> value = new RetentionHoursDebugValueHolder<>(holder);
    RetentionHoursDebugVO vo = RetentionHoursDebugVO.from(1);
    RetentionHoursDebugVO other = RetentionHoursDebugVO.from(1);
    ObservabilityConfig original = Mockito.mock(ObservabilityConfig.class);
    Mockito.when(original.getRetentionHoursDebugValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readRetentionHoursDebug(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNull(value.readRetentionHoursDebug(Optional.empty(), fails),
        "Without value and original there is no result");
    Assertions.assertFalse(fails.isEmpty(), "A required value must be reported as missing");
    value.retentionHoursDebug(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readRetentionHoursDebug(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readRetentionHoursDebug(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of retention hours debug of observability config")
  void test_retention_hours_debug_value_holder_unset() {
    Object holder = new Object();
    RetentionHoursDebugValueHolder<Object> value = new RetentionHoursDebugValueHolder<>(holder);
    RetentionHoursDebugVO vo = RetentionHoursDebugVO.from(1);
    value.retentionHoursDebug(vo);
    Assertions.assertSame(holder,
        value.unsetRetentionHoursDebugIfMatches("retentionHoursDebug_other"));
    Assertions.assertTrue(value.getRetentionHoursDebugValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetRetentionHoursDebugIfMatches("retentionHoursDebug"));
    Assertions.assertFalse(value.getRetentionHoursDebugValue().isPresent(),
        "The field name must clear the value");
    value.retentionHoursDebug(vo);
    Assertions.assertSame(holder, value.unsetRetentionHoursDebug());
    Assertions.assertFalse(value.getRetentionHoursDebugValue().isPresent(),
        "Unset must clear the value");
  }
}
